-- DG-12 / sello de resolución del fixture V20 (concat_ws con '|'): ambigüedad de serialización (DEFECTO CONFIRMADO si OK)
select t('EX-DG12a','DG-12','DEFECTO: concat_ws(''|'',…) hace que (''x|y'',''z'') y (''x'',''y|z'') produzcan el MISMO SHA-256 (separador ambiguo)','OK','do $$ begin if sha256(convert_to(concat_ws(''|'',''x|y'',''z''),''UTF8'')) <> sha256(convert_to(concat_ws(''|'',''x'',''y|z''),''UTF8'')) then raise exception ''SIN_COLISION''; end if; end $$');
select t('EX-DG12b','DG-12','DEFECTO: concat_ws omite NULL: (''a'',NULL,''b'') y (''a'',''b'') producen el MISMO SHA-256 (null ambiguo)','OK','do $$ begin if sha256(convert_to(concat_ws(''|'',''a'',null,''b''),''UTF8'')) <> sha256(convert_to(concat_ws(''|'',''a'',''b''),''UTF8'')) then raise exception ''SIN_COLISION''; end if; end $$');
select t('EX-DG12c','DG-12','Serialización JSON array (jsonb_build_array::text) NO colisiona en los mismos casos','OK','do $$ begin if sha256(convert_to(jsonb_build_array(''x|y'',''z'')::text,''UTF8'')) = sha256(convert_to(jsonb_build_array(''x'',''y|z'')::text,''UTF8'')) or sha256(convert_to(jsonb_build_array(''a'',null,''b'')::text,''UTF8'')) = sha256(convert_to(jsonb_build_array(''a'',''b'')::text,''UTF8'')) then raise exception ''COLISION''; end if; end $$');
